const CONFIG={TEXTS:["10% of 5500","time in london","12 + 12 + sin(10)","100 KG to G","now + 3 days","30 °C to °F","now + 3 days","rgb(255,0,0) to hex"],TYPING_SPEED:50,DELETING_SPEED:30,FIRST_WORD_EXTRA_DELAY:800,WORD_DELAY:1400,START_DELAY:800,BETWEEN_WORD_DELAY:250,RANDOMIZE_SPEED:!0,RANDOM_RANGE:30,LOOP:!0};!function(){const E=document.getElementById("typing-calc");if(!E)return;let t=0,n=0,e=!1;function D(E){if(!CONFIG.RANDOMIZE_SPEED)return E;return E+Math.random()*CONFIG.RANDOM_RANGE}function O(){const N=CONFIG.TEXTS[t];let T;if(n+=e?-1:1,E.textContent=N.substring(0,n),e||n!==N.length)if(e&&0===n){if(e=!1,t++,t>=CONFIG.TEXTS.length){if(!CONFIG.LOOP)return;t=0}T=CONFIG.BETWEEN_WORD_DELAY}else T=D(e?CONFIG.DELETING_SPEED:CONFIG.TYPING_SPEED);else e=!0,T=CONFIG.WORD_DELAY+(0===t?CONFIG.FIRST_WORD_EXTRA_DELAY:0);setTimeout(()=>requestAnimationFrame(O),T)}setTimeout(()=>{requestAnimationFrame(O)},CONFIG.START_DELAY)}();